ALTER TABLE member_user ADD experience BIGINT NOT NULL DEFAULT 0;
ALTER TABLE member_user ADD level_id BIGINT NULL;
ALTER TABLE member_user ADD group_id BIGINT NULL;
ALTER TABLE member_user ADD sex INT NULL;
ALTER TABLE member_user ADD birthday DATE NULL;
CREATE TABLE member_session(id VARCHAR(36) PRIMARY KEY,member_id BIGINT NOT NULL,access_hash VARCHAR(64) NOT NULL UNIQUE,refresh_hash VARCHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,refresh_expires_at DATETIME NOT NULL,FOREIGN KEY(member_id) REFERENCES member_user(id),KEY idx_member_session_owner(member_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_address(id BIGINT AUTO_INCREMENT PRIMARY KEY,member_id BIGINT NOT NULL,name VARCHAR(80) NOT NULL,mobile VARCHAR(24) NOT NULL,area_id BIGINT NOT NULL,detail_address VARCHAR(500) NOT NULL,default_status BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(member_id) REFERENCES member_user(id),KEY idx_member_address_owner(member_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_level(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,level INT NOT NULL UNIQUE,experience BIGINT NOT NULL UNIQUE,discount_percent INT NOT NULL,icon VARCHAR(500),background_url VARCHAR(500),status INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_group(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,remark VARCHAR(500),status INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_tag(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,remark VARCHAR(500)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_tag_link(member_id BIGINT NOT NULL,tag_id BIGINT NOT NULL,PRIMARY KEY(member_id,tag_id),FOREIGN KEY(member_id) REFERENCES member_user(id),FOREIGN KEY(tag_id) REFERENCES member_tag(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_level_record(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,level_id BIGINT NULL,user_experience BIGINT NOT NULL,experience BIGINT NULL,level INT NULL,discount_percent INT NULL,remark VARCHAR(500) NOT NULL,description VARCHAR(500) NULL,create_time DATETIME NOT NULL,create_by VARCHAR(64) NULL,update_by VARCHAR(64) NULL,update_time DATETIME NULL,FOREIGN KEY(user_id) REFERENCES member_user(id),KEY idx_member_level_record(user_id,id));
CREATE TABLE member_sign_config(signin_day INT PRIMARY KEY,point BIGINT NOT NULL,experience BIGINT NOT NULL,status INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_sign_in_record(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,sign_date DATE NOT NULL,`day` INT NOT NULL,point BIGINT NOT NULL,experience BIGINT NOT NULL,create_time DATETIME NULL,create_by VARCHAR(64) NULL,update_by VARCHAR(64) NULL,update_time DATETIME NULL,UNIQUE KEY uk_member_sign_date(user_id,sign_date),FOREIGN KEY(user_id) REFERENCES member_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE member_config(id INT PRIMARY KEY,point_trade_deduct_enable BOOLEAN NOT NULL,point_trade_deduct_unit_price INT NOT NULL,point_trade_deduct_max_price INT NOT NULL,point_trade_give_point INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO member_config VALUES(1,FALSE,0,0,0);
CREATE TABLE member_login_attempt(login_hash VARCHAR(64) PRIMARY KEY,failures INT NOT NULL DEFAULT 0,window_start DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE member_user ADD CONSTRAINT fk_member_level FOREIGN KEY(level_id) REFERENCES member_level(id);
ALTER TABLE member_user ADD CONSTRAINT fk_member_group FOREIGN KEY(group_id) REFERENCES member_group(id);
